/**
 * The animated listing preview, as a GIF.
 *
 * Same six-second story as wall/preview-etch.css, so the GIF and the live
 * card cannot tell different stories:
 *
 *   0.00-0.22  the address types itself
 *   0.22-0.38  the code builds, in the brand indigo
 *   0.36-0.44  the Etch mark lands in the middle
 *   0.38-0.72  a scan line passes over it
 *   0.40-0.62  four scan conditions tick through
 *   0.74-1.00  the pass badge lands and holds
 *
 * The QR in it is real: generated by this app's encoder, styled indigo with a
 * centre logo, and put through the app's own four-condition scan test before
 * anything is drawn.
 *
 * Run: node scripts/make-wall-gif.mjs
 * Output: wall/etch-preview.gif
 */

import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { encode } from '../src/core/encode.js';
import { rasterize } from '../src/core/render/rasterize.js';
import { verify } from '../src/core/verify.js';
import { normaliseStyle } from '../src/core/style.js';
import { encodeGif, quantise } from './lib/gif.mjs';
import {
  makeCanvas, fillRect, fillCircle, blit, drawText, measure, roundedRect, drawMark, drawTick,
  PAPER, WHITE, ACCENT, MUTED, LINE, OK, OK_SOFT,
} from './lib/draw.mjs';

const here = dirname(fileURLToPath(import.meta.url));

const W = 480;
const H = 300;
const FRAMES = 60;
const DELAY_CS = 10; // hundredths of a second, so 60 frames is six seconds
const URL = 'https://etch.vibe-coding.fans/';
const URL_SHOWN = 'HTTPS://ETCH.VIBE-CODING.FANS/';
const INDIGO = '#4338CA';

/** Linear interpolation between two colours, for fades over a flat ground. */
const mix = (bg, fg, t) => [
  bg[0] + (fg[0] - bg[0]) * t,
  bg[1] + (fg[1] - bg[1]) * t,
  bg[2] + (fg[2] - bg[2]) * t,
];

/** Ramp from 0 to 1 across [a, b], flat outside. */
const ramp = (t, a, b) => (t <= a ? 0 : t >= b ? 1 : (t - a) / (b - a));

/* ------------------------------------------------------------- the code -- */

const result = encode(URL, { ecc: 'Q', boostEcc: false });
const { style } = normaliseStyle({
  foreground: INDIGO,
  background: '#FFFFFF',
  logo: { href: '', sizeRatio: 0.2, padding: 1, shape: 'square', plate: '#FFFFFF' },
});

const check = await verify(result.matrix, result.version, URL, { style });
if (!check.pass) {
  throw new Error(`The GIF's QR does not decode under: ${check.failedIds.join(', ')}.`);
}

const CODE_PX = 150;
const modulePx = Math.max(1, Math.round(CODE_PX / (result.size + 8)));
const qr = rasterize(result.matrix, result.version, { style, modulePx });


/**
 * Decode the pixels that actually ship.
 *
 * verify() above checks a model of the code, in which the logo area is treated
 * as lost. This reads the composed image back instead, mark and all, so what is
 * asserted is the thing in the file rather than a description of it.
 *
 * @param {{data: Uint8ClampedArray, width: number}} canvas
 * @param {number} x @param {number} y @param {number} w @param {number} h
 * @param {string} expected
 */
async function assertRegionDecodes(canvas, x, y, w, h, expected) {
  const { default: jsQR } = await import('jsqr');
  const region = new Uint8ClampedArray(w * h * 4);
  for (let row = 0; row < h; row++) {
    const from = ((y + row) * canvas.width + x) * 4;
    region.set(canvas.data.subarray(from, from + w * 4), row * w * 4);
  }
  const found = jsQR(region, w, h, { inversionAttempts: 'dontInvert' });
  if (!found || found.data !== expected) {
    throw new Error(`The composed image does not decode to ${expected}: got ${JSON.stringify(found?.data ?? null)}`);
  }
  return found.data;
}

/* ---------------------------------------------------------- the frames -- */

const BAR_H = 52;
const PAD = 22;
const codeX = PAD;
const codeY = BAR_H + Math.round((H - BAR_H - qr.height) / 2);
const listX = codeX + qr.width + 26;

const CHECKS = ['AS EXPORTED', 'SMALL, OR FAR AWAY', 'CHEAP PRINTING', 'PHONE CAMERA'];
const CHECK_CAP = 15;
const CHECK_GAP = 30;
const listTop = codeY + 8;

const frames = [];
for (let i = 0; i < FRAMES; i++) {
  const t = i / FRAMES;
  const c = makeCanvas(W, H, PAPER);

  // Address bar.
  fillRect(c, 0, 0, W, BAR_H, WHITE);
  fillRect(c, 0, BAR_H - 1, W, 1, LINE);
  fillCircle(c, PAD + 5, BAR_H / 2, 5, ACCENT);

  const typed = Math.round(URL_SHOWN.length * ramp(t, 0, 0.22));
  if (typed > 0) drawText(c, URL_SHOWN, PAD + 18, BAR_H / 2 - 7, 14, MUTED, { maxChars: typed });
  if (t < 0.22) {
    const caretX = PAD + 18 + measure(URL_SHOWN.slice(0, typed), 14) + 3;
    fillRect(c, caretX, BAR_H / 2 - 8, 1.5, 16, ACCENT);
  }

  // The code, wiping in left to right.
  const build = ramp(t, 0.22, 0.38);
  if (build > 0) {
    // The paper wipes in with the pattern rather than ahead of it, so the
    // first beat is not a blank white box sitting there waiting.
    const revealed = Math.round(qr.width * build);
    fillRect(c, codeX, codeY, revealed, qr.height, WHITE);
    blit(c, qr, codeX, codeY, revealed);
  }

  // The mark, landing once the pattern is finished.
  const landed = ramp(t, 0.36, 0.44);
  if (landed > 0) {
    const full = result.size * 0.2 * modulePx;
    const size = full * (0.55 + 0.45 * landed);
    const cx = codeX + qr.width / 2;
    const cy = codeY + qr.height / 2;
    const plate = full + 2 * modulePx;
    fillRect(c, cx - plate / 2, cy - plate / 2, plate, plate, WHITE);
    drawMark(c, cx - size / 2, cy - size / 2, size, ACCENT, WHITE);
  }

  // One scan sweep over the finished code.
  const sweep = ramp(t, 0.38, 0.72);
  if (sweep > 0 && sweep < 1) {
    const inset = 4 * modulePx;
    const y = codeY + inset + (qr.height - inset * 2) * sweep;
    fillRect(c, codeX + inset, y, qr.width - inset * 2, 2, ACCENT);
  }

  // The four conditions, ticking through.
  CHECKS.forEach((label, n) => {
    const appear = ramp(t, 0.4 + n * 0.05, 0.47 + n * 0.05);
    if (appear <= 0) return;
    const y = listTop + n * CHECK_GAP;
    fillCircle(c, listX + 9, y + CHECK_CAP / 2, 9, mix(PAPER, OK, appear));
    drawTick(c, listX + 9, y + CHECK_CAP / 2, 9, mix(OK, WHITE, appear));
    drawText(c, label, listX + 26, y, CHECK_CAP, mix(PAPER, MUTED, appear));
  });

  // The verdict.
  const pass = ramp(t, 0.74, 0.82);
  if (pass > 0) {
    const cap = 15;
    const text = 'SCAN TEST PASSED';
    const w = measure(text, cap) + 40;
    const y = listTop + CHECKS.length * CHECK_GAP + 4;
    roundedRect(c, listX, y, w + 22, cap + 18, (cap + 18) / 2, mix(PAPER, OK_SOFT, pass));
    drawTick(c, listX + 20, y + (cap + 18) / 2, 8, mix(OK_SOFT, OK, pass));
    drawText(c, text, listX + 34, y + 9, cap, mix(OK_SOFT, OK, pass));
  }

  frames.push(c);
}

/* ------------------------------------------------------------ the file -- */

// The last frame is the one people look at: check its code really reads.
const settled = frames[FRAMES - 1];
const decoded = await assertRegionDecodes(settled, codeX, codeY, qr.width, qr.height, URL);

const { palette, indexed, distinctColours } = quantise(frames);
const gif = encodeGif({
  width: W,
  height: H,
  palette,
  frames: indexed.map((indices) => ({ indices, delayCs: DELAY_CS })),
});

const out = join(here, '..', 'wall', 'etch-preview.gif');
await writeFile(out, gif);

console.log(`etch-preview.gif written: ${W}x${H}, ${FRAMES} frames, ${(FRAMES * DELAY_CS) / 100}s loop`);
console.log(`QR: version ${result.version}, ${result.size} modules, ECC ${result.ecc}, indigo with centre mark`);
console.log(`scan test: ${check.conditions.map((x) => `${x.id} ${x.matched ? 'ok' : 'FAIL'}`).join(', ')}`);
console.log(`colours: ${distinctColours} distinct, quantised to ${palette.length}`);
console.log(`final frame decodes to: ${decoded}`);
console.log(`size: ${(gif.length / 1024).toFixed(0)}KB`);
